create function public.lease_quote_notification(p_quote uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare recipient text;row_data private.notification_outbox;begin
 select value->>'recipient' into recipient from private.integration_settings where key='quote_notifications' and value->>'enabled'='true';if recipient is null then return null;end if;
 select * into row_data from private.notification_outbox where quote_id=p_quote and state in ('queued','failed') and attempts<8 and next_attempt_at<=now() and (locked_until is null or locked_until<now()) for update skip locked;if not found then return null;end if;
 update private.notification_outbox set locked_until=now()+interval '2 minutes',attempts=attempts+1 where id=row_data.id;return jsonb_build_object('recipient',recipient);end $$;
create function public.finish_quote_notification(p_quote uuid,p_success boolean,p_message text default null) returns void language plpgsql security definer set search_path='' as $$begin update private.notification_outbox set state=case when p_success then 'sent' else 'failed' end,locked_until=null,provider_message_id=case when p_success then p_message else null end,last_error=case when p_success then null else 'E-posta sağlayıcısına ulaşılamadı.' end,next_attempt_at=now()+interval '10 minutes' where quote_id=p_quote and locked_until is not null;end $$;
create function public.pending_quote_notifications() returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(quote_id),'[]') from(select quote_id from private.notification_outbox where state in ('queued','failed') and attempts<8 and next_attempt_at<=now() order by next_attempt_at limit 20)t$$;
revoke all on function public.lease_quote_notification(uuid),public.finish_quote_notification(uuid,boolean,text),public.pending_quote_notifications() from public,anon,authenticated;
grant execute on function public.lease_quote_notification(uuid),public.finish_quote_notification(uuid,boolean,text),public.pending_quote_notifications() to service_role;
create index product_media_asset_lookup on public.product_media(media_id,product_id);
notify pgrst,'reload schema';
